  useEffect(() => {
    const timer = setTimeout(() => setShowBars(true), 50);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    const node = statsRef.current;
    if (!node || statsAnimated) return;

    const animateCounters = () => {
      const duration = 2000;
      const start = performance.now();
      const targets = { projects: 10, hours: 100, clients: 5 };

      const step = (now) => {
        const elapsed = now - start;
        const progress = Math.min(elapsed / duration, 1);
        const easeOut = 1 - Math.pow(1 - progress, 3);

        setAnimatedStats({
          projects: Math.round(targets.projects * easeOut),
          hours: Math.round(targets.hours * easeOut),
          clients: Math.round(targets.clients * easeOut)
        });

        if (progress < 1) {
          requestAnimationFrame(step);
        }
      };

      requestAnimationFrame(step);
      setStatsAnimated(true);
    };

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            animateCounters();
            observer.disconnect();
          }
        });
      },
      { threshold: 0.3 }
    );

    observer.observe(node);
    return () => observer.disconnect();
  }, [statsAnimated]);

  useEffect(() => {
    if (!selectedInsight) return;

    const handleEscape = (event) => {
      if (event.key === 'Escape') {
        setSelectedInsight(null);
      }
    };

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    window.addEventListener('keydown', handleEscape);

    return () => {
      document.body.style.overflow = previousOverflow;
      window.removeEventListener('keydown', handleEscape);
    };
  }, [selectedInsight]);

